/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline 7‑point 3D heat stencil, matching PolyBench semantics.
@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We only update interior points; need at least a 3×3×3 grid.
    assert n > 2

    for t in seq(0, tsteps):
        # Phase 1: update B from A.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # 7‑point stencil in 3D.
                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * A[i, j, k] + A[i - 1, j,     k    ])
                      + 0.125 * (A[i,     j + 1, k    ] - 2.0 * A[i, j, k] + A[i,     j - 1, k    ])
                      + 0.125 * (A[i,     j,     k + 1] - 2.0 * A[i, j, k] + A[i,     j,     k - 1])
                      + A[i, j, k]
                    )

        # Phase 2: update A from B.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    A[i, j, k] = (
                        0.125 * (B[i + 1, j,     k    ] - 2.0 * B[i, j, k] + B[i - 1, j,     k    ])
                      + 0.125 * (B[i,     j + 1, k    ] - 2.0 * B[i, j, k] + B[i,     j - 1, k    ])
                      + 0.125 * (B[i,     j,     k + 1] - 2.0 * B[i, j, k] + B[i,     j,     k - 1])
                      + B[i, j, k]
                    )


# --------------------------------------------------------------------
# Performance schedule
#
# We:
#   * tile the outer spatial loop (i dimension) to improve cache reuse,
#   * parallelize the outer tile loops across cores,
#   * and simplify the resulting code.
#
# Tiling is only applied along i; j and k already give good stride‑1
# access along k and moderate locality along j.
# --------------------------------------------------------------------

# Tile factor for the i (row) dimension.
Ti = 32

# ---------------------------
# Phase 1: A -> B
# ---------------------------

# The first i-loop inside the time loop belongs to Phase 1.
# 1) Shift its lower bound from [1, n-1) to [0, n-2) so that divide_loop
#    (shown in the docs for loops starting at 0) applies directly.
kernel_heat_3d = shift_loop(kernel_heat_3d, "i #0", "0")

# 2) Tile the shifted i-loop: i = 32 * io0 + ii0 (with a clean tail loop).
kernel_heat_3d = divide_loop(kernel_heat_3d, "i #0", Ti, ["io0", "ii0"], tail="cut")

# 3) Parallelize the outer i-tile loop of Phase 1. This becomes
#    an OpenMP parallel for in the generated C, distributing
#    independent i-slices of the 3D grid across cores.
kernel_heat_3d = parallelize_loop(kernel_heat_3d, "io0 #0")

# ---------------------------
# Phase 2: B -> A
# ---------------------------

# After transforming Phase 1 there is one remaining i-loop, in Phase 2.
# 1) Shift its lower bound to start at 0 for the same reason as above.
kernel_heat_3d = shift_loop(kernel_heat_3d, "i", "0")

# 2) Tile the Phase 2 i-loop with the same tile size for symmetry.
kernel_heat_3d = divide_loop(kernel_heat_3d, "i #0", Ti, ["io1", "ii1"], tail="cut")

# 3) Parallelize the outer tile loop of Phase 2.
kernel_heat_3d = parallelize_loop(kernel_heat_3d, "io1")

# Finally, simplify the scheduled kernel to clean up the generated code.
kernel_heat_3d = simplify(kernel_heat_3d)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);

