/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


@proc
def kernel_heat_3d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only interior points, so require at least a 3x3x3 grid.
    assert n > 2

    # Time-stepping loop.
    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # Update B from A (Jacobi step) on the interior region.
        # Loops are written with 0-based indices:
        #   logical indices I = i + 1, J = j + 1, K = k + 1 in [1, n-2].
        # This matches the original PolyBench kernel, which iterates
        # i,j,k from 1 to n-2, but is easier to schedule.
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                for k in seq(0, n - 2):
                    B[i + 1, j + 1, k + 1] = (
                        0.125
                        * (
                            A[i + 2, j + 1, k + 1]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i,     j + 1, k + 1]
                        )
                        + 0.125
                        * (
                            A[i + 1, j + 2, k + 1]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i + 1, j,     k + 1]
                        )
                        + 0.125
                        * (
                            A[i + 1, j + 1, k + 2]
                            - 2.0 * A[i + 1, j + 1, k + 1]
                            + A[i + 1, j + 1, k    ]
                        )
                        + A[i + 1, j + 1, k + 1]
                    )

        # ------------------------------------------------------------------
        # Update A from B using the same 7-point stencil.
        # ------------------------------------------------------------------
        for i in seq(0, n - 2):
            for j in seq(0, n - 2):
                for k in seq(0, n - 2):
                    A[i + 1, j + 1, k + 1] = (
                        0.125
                        * (
                            B[i + 2, j + 1, k + 1]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i,     j + 1, k + 1]
                        )
                        + 0.125
                        * (
                            B[i + 1, j + 2, k + 1]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i + 1, j,     k + 1]
                        )
                        + 0.125
                        * (
                            B[i + 1, j + 1, k + 2]
                            - 2.0 * B[i + 1, j + 1, k + 1]
                            + B[i + 1, j + 1, k    ]
                        )
                        + B[i + 1, j + 1, k + 1]
                    )


# ---------------------------
# Scheduling / optimization
# ---------------------------

# Start from the base kernel.
kernel_heat_3d_sched = kernel_heat_3d_base

# Parallelize the spatial i-loop in the A->B update.
# This loop is fully independent across i because each output cell
# B[i+1,j+1,k+1] depends only on the previous-time-step array A.
b_assign = kernel_heat_3d_sched.find("B[_,_,_] = _")
k_B = b_assign.parent()   # for k in ...
j_B = k_B.parent()        # for j in ...
i_B = j_B.parent()        # for i in ...
kernel_heat_3d_sched = parallelize_loop(kernel_heat_3d_sched, i_B)

# Parallelize the spatial i-loop in the B->A update.
# Similarly, each A[i+1,j+1,k+1] depends only on B from the same time
# step, so the i-loop is also embarrassingly parallel.
a_assign = kernel_heat_3d_sched.find("A[_,_,_] = _")
k_A = a_assign.parent()
j_A = k_A.parent()
i_A = j_A.parent()
kernel_heat_3d_sched = parallelize_loop(kernel_heat_3d_sched, i_A)

# Run a simplification pass to clean up the IR after transformations.
kernel_heat_3d_sched = simplify(kernel_heat_3d_sched)

# Expose the optimized kernel under the name expected by the C driver.
kernel_heat_3d = rename(kernel_heat_3d_sched, "kernel_heat_3d")

