EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline 7-point 3D heat stencil, written in Exo.
@proc
def kernel_heat_3d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only interior points [1, n-2] in each dimension.
    assert n > 2

    for t in seq(0, tsteps):
        # Update B from A.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # Cache the center value once to avoid repeated loads.
                    a_center: DATA_TYPE
                    a_center = A[i, j, k]

                    B[i, j, k] = (
                        0.125 * (A[i + 1, j,     k    ] - 2.0 * a_center + A[i - 1, j,     k    ])
                      + 0.125 * (A[i,     j + 1, k    ] - 2.0 * a_center + A[i,     j - 1, k    ])
                      + 0.125 * (A[i,     j,     k + 1] - 2.0 * a_center + A[i,     j,     k - 1])
                      + a_center
                    )

        # Update A from B.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # Similarly cache the center from B.
                    b_center: DATA_TYPE
                    b_center = B[i, j, k]

                    A[i, j, k] = (
                        0.125 * (B[i + 1, j,     k    ] - 2.0 * b_center + B[i - 1, j,     k    ])
                      + 0.125 * (B[i,     j + 1, k    ] - 2.0 * b_center + B[i,     j - 1, k    ])
                      + 0.125 * (B[i,     j,     k + 1] - 2.0 * b_center + B[i,     j,     k - 1])
                      + b_center
